function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const { z } = require("zod");
const s = z.discriminatedUnion("type", [z.object({ type: z.literal("a") }), z.object({ type: z.literal("b") })]);
const r = s.safeParse({ type: "c" });
if (r.success) broken("parse of an unknown discriminator succeeded");
const issue = r.error.issues[0];
if (!issue || issue.code !== "invalid_union" || issue.discriminator !== "type") broken("unexpected issue " + JSON.stringify(r.error.issues));
if (issue.message === "Invalid input" && issue.options === undefined) symptom("z.discriminatedUnion issue has no options and its message is Invalid input");
if (JSON.stringify(issue.options) !== JSON.stringify(["a", "b"])) broken("options were " + JSON.stringify(issue.options));
if (issue.message !== "Invalid discriminator value. Expected 'a' | 'b'") broken("message was " + issue.message);
console.log("OK: z.discriminatedUnion issue has options a, b and message: " + issue.message);

